CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sources (id text PRIMARY KEY, data jsonb NOT NULL, next_run_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS raw_items (source_id text NOT NULL REFERENCES sources(id), identifier text NOT NULL, raw_hash text NOT NULL, file_path text NOT NULL, data jsonb NOT NULL, collected_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(source_id,identifier,raw_hash));
CREATE TABLE IF NOT EXISTS records (id text PRIMARY KEY, source_id text NOT NULL REFERENCES sources(id), external_id text NOT NULL, status text NOT NULL CHECK(status IN ('draft','review','published','withdrawn')), data jsonb NOT NULL, raw_hash text NOT NULL, revision integer NOT NULL CHECK(revision>0), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,external_id));
CREATE TABLE IF NOT EXISTS record_versions (record_id text NOT NULL REFERENCES records(id), revision integer NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(record_id,revision));
CREATE TABLE IF NOT EXISTS withdrawals (record_id text PRIMARY KEY REFERENCES records(id), reason text NOT NULL, withdrawn_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('collect','normalize','publish')), state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','retry','done','failed')), payload jsonb NOT NULL, dedupe_key text NOT NULL, attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, run_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, owner text, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS jobs_active_dedupe ON jobs(dedupe_key) WHERE state IN ('queued','running','retry');
CREATE INDEX IF NOT EXISTS jobs_ready ON jobs(state,run_at);
CREATE TABLE IF NOT EXISTS publications (id text PRIMARY KEY, target text NOT NULL, status text NOT NULL CHECK(status IN ('prepared','published','failed')), record_count integer NOT NULL, manifest jsonb NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, last_error text);
CREATE TABLE IF NOT EXISTS audit_log (id text PRIMARY KEY, operation text NOT NULL, actor text NOT NULL, resource_id text, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS requests (id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('correction','contribution','privacy')), record_id text, message text NOT NULL, contact text, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewing','resolved','rejected')), resolution text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog (kind text NOT NULL, id text NOT NULL, data jsonb NOT NULL, PRIMARY KEY(kind,id));
CREATE INDEX IF NOT EXISTS records_status_updated ON records(status,updated_at);
